    param(
        [Parameter(Mandatory=$true)]
        [int]$Port
    )

    <#
    .SYNOPSIS
    Checks if a specific TCP port is currently in a listening state on the local machine.

    .DESCRIPTION
    This function uses Get-NetTCPConnection to query active network connections and determines if any process is actively listening on the specified TCP port.

    .PARAMETER Port
    The TCP port number to check for listening status. Must be an integer between 1 and 65535.

    .EXAMPLE
    Test-TcpPortListening -Port 80

    .EXAMPLE
    Test-TcpPortListening -Port 443 | Select-Object State, OwningProcess
    #>
    try {
        $connection = Get-NetTCPConnection -LocalPort $Port -ErrorAction Stop
        if ($connection) {
            return $true
        } else {
            return $false
        }
    } catch {
        Write-Error "An error occurred while checking the port: $($_.Exception.Message)"
        return $false
    }
}
