using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;

public class WordCounter
{
    public static void Main(string[] args)
    {
        if (args.Length == 0)
        {
            Console.WriteLine("Please provide a text file as an argument.");
            return;
        }

        string filePath = args[0];
        if (!File.Exists(filePath))
        {
            Console.WriteLine("The specified file does not exist.");
            return;
        }

        try
        {
            string content = File.ReadAllText(filePath);
            var wordCounts = new Dictionary<string, int>();

            // Simple tokenization: split by non-alphanumeric characters and convert to lower case
            string[] words = content.Split(new char[] { ' ', '\r', '\n', '.', ',', '!', '?', ';', ':', '"', "'", '-', '(', ')', '[', ']', '{', '}', '/', '\\' }, StringSplitOptions.RemoveEmptyEntries);

            foreach (var word in words)
            {
                string normalizedWord = word.ToLower();
                if (!wordCounts.ContainsKey(normalizedWord))
                {
                    wordCounts[normalizedWord] = 0;
                }
                wordCounts[normalizedWord]++;
            }

            // Get the top 10 most frequent words
            var topWords = wordCounts.OrderByDescending(kvp => kvp.Value)
                                     .Take(10)
                                     .ToList();

            Console.WriteLine("Top 10 Most Frequent Words:");
            foreach (var item in topWords)
            {
                Console.WriteLine($"{item.Key}: {item.Value}");
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine("An error occurred: " + ex.Message);
        }
    }
}
