using System;
using System.IO;

public class FileLister
{
    public static void Main(string[] args)
    {
        if (args.Length == 0)
        {
            Console.WriteLine("Usage: FileLister <folderPath>");
            return;
        }

        string startPath = args[0];
        long minSize = 100 * 1024 * 1024; // 100 MB in bytes

        if (!Directory.Exists(startPath))
        {
            Console.WriteLine("Error: Directory not found.");
            return;
        }

        ListFilesRecursive(startPath, minSize);
    }

    private static void ListFilesRecursive(string currentDirectory, long minSize)
    {
        try
        {
            // Process files in the current directory
            foreach (FileInfo fileInfo in new DirectoryInfo(currentDirectory).GetFiles())
            {
                if (fileInfo.Length > minSize)
                {
                    Console.WriteLine($"{fileInfo.FullName} ({fileInfo.Length / (1024 * 1024.0):F2} MB)");
                }
            }

            // Recurse into subdirectories
            foreach (DirectoryInfo subdirectory in new DirectoryInfo(currentDirectory).GetDirectories())
            {
                ListFilesRecursive(subdirectory.FullName, minSize);
            }
        }
        catch (UnauthorizedAccessException)
        {
            Console.WriteLine($"Access denied: {currentDirectory}");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred while processing {currentDirectory}: {ex.Message}");
        }
    }
}
```

