using System;
using System.Collections.Generic;

public class LruCache<TKey, TValue>
{
    private readonly int _capacity;
    private readonly Dictionary<TKey, LinkedListNode<CacheEntry<TKey, TValue>>> _map;
    private readonly LinkedList<CacheEntry<TKey, TValue>> _list;

    private class CacheEntry<TKey, TValue>
    {
        public TKey Key { get; set; }
        public TValue Value { get; set; }
    }

    public LruCache(int capacity)
    {
        if (capacity <= 0) throw new ArgumentException("Capacity must be positive.");
        _capacity = capacity;
        _map = new Dictionary<TKey, LinkedListNode<CacheEntry<TKey, TValue>>>();
        _list = new LinkedList<CacheEntry<TKey, TValue>>();
    }

    public bool TryGet(TKey key, out TValue value)
    {
        if (_map.TryGetValue(key, out var node))
        {
            // Move to front (most recently used)
            _list.Remove(node);
            _list.AddFirst(node);
            value = node.Value.Value;
            return true;
        }
        value = default(TValue);
        return false;
    }

    public void Put(TKey key, TValue value)
    {
        if (_map.ContainsKey(key))
        {
            // Update existing item and move to front
            var node = _map[key];
            node.Value.Value = value;
            _list.Remove(node);
            _list.AddFirst(node);
            return;
        }

        if (_list.Count >= _capacity)
        {
            // Evict least recently used (tail of the list)
            var lruNode = _list.Last;
            if (lruNode != null)
            {
                _map.Remove(lruNode.Value.Key);
                _list.RemoveLast();
            }
        }

        // Add new item to front
        var entry = new CacheEntry<TKey, TValue> { Key = key, Value = value };
        var newNode = _list.AddFirst(entry);
        _map[key] = newNode;
    }
}

public class Program
{
    public static void Main(string[] args)
    {
        // Note: For true thread safety in a multi-threaded environment, 
        // locks or concurrent collections should wrap the access to LruCache methods.
        var cache = new LruCache<string, int>(3);

        cache.Put("A", 10);
        cache.Put("B", 20);
        cache.Put("C", 30);

        Console.WriteLine(string.Format("Get A: {0}", cache.TryGet("A", out int valA) ? valA : -1)); // Should be 10 (MRU)
        cache.Put("D", 40); // Evicts B (LRU)

        Console.WriteLine(string.Format("Get B: {0}", cache.TryGet("B", out int valB) ? valB : -1)); // Should be -1
        Console.WriteLine(string.Format("Get C: {0}", cache.TryGet("C", out int valC) ? valC : -1)); // Should be 30 (Now MRU after A was accessed)

        cache.Put("E", 50); // Evicts A (LRU)
        Console.WriteLine(string.Format("Get A: {0}", cache.TryGet("A", out int valA2) ? valA2 : -1)); // Should be -1
    }
}
```

