using System;

public class BinarySearchTree<T>
{
    private Node<T> root;

    private class Node<T>
    {
        public T Value { get; set; }
        public Node<T> Left { get; set; }
        public Node<T> Right { get; set; }

        public Node(T value)
        {
            Value = value;
        }
    }

    public void Insert(T value)
    {
        root = InsertRecursive(root, value);
    }

    private Node<T> InsertRecursive(Node<T> node, T value)
    {
        if (node == null)
        {
            return new Node<T>(value);
        }

        // Assuming T implements IComparable for comparison in a BST
        if (Comparer<T>.Default.Compare(value, node.Value) < 0)
        {
            node.Left = InsertRecursive(node.Left, value);
        }
        else if (Comparer<T>.Default.Compare(value, node.Value) > 0)
        {
            node.Right = InsertRecursive(node.Right, value);
        }

        return node;
    }

    public bool Contains(T value)
    {
        return ContainsRecursive(root, value);
    }

    private bool ContainsRecursive(Node<T> node, T value)
    {
        if (node == null)
            return false;

        int comparison = Comparer<T>.Default.Compare(value, node.Value);
        if (comparison == 0)
            return true;
        else if (comparison < 0)
            return ContainsRecursive(node.Left, value);
        else
            return ContainsRecursive(node.Right, value);
    }

    public void InOrderTraversal()
    {
        Console.Write("In-order traversal: ");
        InOrderRecursive(root);
        Console.WriteLine();
    }

    private void InOrderRecursive(Node<T> node)
    {
        if (node != null)
        {
            InOrderRecursive(node.Left);
            Console.Write(node.Value + " ");
            InOrderRecursive(node.Right);
        }
    }
}

