public class FolderWatcher
{
    private static FileSystemWatcher watcher;

    public static void Main(string[] args)
    {
        if (args.Length == 0)
        {
            Console.WriteLine("Usage: FolderWatcher <path_to_watch>");
            return;
        }

        string path = args[0];
        if (!Directory.Exists(path))
        {
            Console.WriteLine($"Error: Directory not found at {path}");
            return;
        }

        watcher = new FileSystemWatcher(path)
        {
            IncludeSubdirectories = false,
            NotifyFilter = NotifyFilters.FileName | NotifyFilters.LastWrite
        };

        watcher.Created += OnFileChanged;
        watcher.Changed += OnFileChanged;
        watcher.Deleted += OnFileChanged;
        watcher.Renamed += OnFileChanged;

        watcher.EnableRaisingEvents = true;
        Console.WriteLine($"Watching folder: {path}. Press Enter to stop.");
        Console.ReadLine();
    }

    private static void OnFileChanged(object sender, FileSystemEventArgs e)
    {
        if (e.ChangeType == WatcherChangeType.Created)
            Console.WriteLine("Created: " + e.Name);
        else if (e.ChangeType == WatcherChangeType.Changed)
            Console.WriteLine("Changed: " + e.Name);
        else if (e.ChangeType == WatcherChangeType.Deleted)
            Console.WriteLine("Deleted: " + e.Name);
    }

    private static void OnFileRenamed(object sender, RenamedEventArgs e)
    {
        Console.WriteLine($"Renamed: {e.OldName} -> {e.Name}");
    }
}
