public class FileLister
{
    public static void Main(string[] args)
    {
        if (args.Length == 0)
        {
            Console.WriteLine("Usage: FileLister <directory>");
            return;
        }

        string startPath = args[0];
        long minSize = 100 * 1024 * 1024; // 100 MB in bytes

        if (!Directory.Exists(startPath))
        {
            Console.WriteLine("Error: Directory not found.");
            return;
        }

        try
        {
            ListFilesRecursively(startPath, minSize);
        }
        catch (Exception ex)
        {
            Console.WriteLine("An error occurred: " + ex.Message);
        }
    }

    private static void ListFilesRecursively(string currentDirectory, long minSizeBytes)
    {
        try
        {
            // Get all files in the current directory
            string[] files = Directory.GetFiles(currentDirectory);
            foreach (string file in files)
            {
                FileInfo fi = new FileInfo(file);
                if (fi.Length >= minSizeBytes)
                {
                    Console.WriteLine($"{fi.FullName} ({fi.Length / (1024 * 1024)} MB)");
                }
            }

            // Get all subdirectories
            string[] subDirectories = Directory.GetDirectories(currentDirectory);
            foreach (string subDir in subDirectories)
            {
                ListFilesRecursively(subDir, minSizeBytes);
            }
        }
        catch (UnauthorizedAccessException)
        {
            Console.WriteLine("Access denied to a directory.");
        }
        catch (Exception ex)
        {
            Console.WriteLine("Error processing directory: " + ex.Message);
        }
    }
}
