public class CsvParser
{
    public static List<string> SplitCsvLine(string line)
    {
        List<string> fields = new List<string>();
        StringBuilder currentField = new StringBuilder();
        bool inQuotes = false;

        for (int i = 0; i < line.Length; i++)
        {
            char c = line[i];

            if (c == '"')
            {
                // Check for escaped quote ("")
                if (inQuotes && i + 1 < line.Length && line[i + 1] == '"')
                {
                    currentField.Append('"');
                    i++; // Skip the next quote
                }
                else
                {
                    inQuotes = !inQuotes;
                }
            }
            else if (c == ',' && !inQuotes)
            {
                fields.Add(currentField.ToString());
                currentField.Clear();
            }
            else
            {
                currentField.Append(c);
            }
        }

        // Add the last field
        fields.Add(currentField.ToString());
        return fields;
    }

    public static void Main(string[] args)
    {
        // Test case 1: Simple CSV
        string line1 = "apple,banana,cherry";
        List<string> result1 = SplitCsvLine(line1);
        Console.WriteLine("Test 1:");
        foreach (var field in result1)
        {
            Console.WriteLine($"'{field}'");
        }

        // Test case 2: Quoted fields with commas and escaped quotes
        string line2 = "Name,\"Product, Deluxe\",Description=\"This is a \"\"quoted\"\" description.\"";
        List<string> result2 = SplitCsvLine(line2);
        Console.WriteLine("\nTest 2:");
        foreach (var field in result2)
        {
            Console.WriteLine($"'{field}'");
        }

        // Test case 3: Empty fields and surrounding spaces (though trimming isn't explicitly required by the prompt, it's good practice for CSV parsing)
        string line3 = "a,,c,\"d with space\"";
        List<string> result3 = SplitCsvLine(line3);
        Console.WriteLine("\nTest 3:");
        foreach (var field in result3)
        {
