using System;
using System.Collections.Generic;

public class LruCache<TKey, TValue>
{
    private readonly Dictionary<TKey, LinkedListNode<KeyValuePair<TKey, TValue>>> _cache = new Dictionary<TKey, LinkedListNode<KeyValuePair<TKey, TValue>>>();
    private readonly LinkedList<KeyValuePair<TKey, TValue>> _list = new LinkedList<KeyValuePair<TKey, TValue>>();
    private readonly int _capacity;

    public LruCache(int capacity)
    {
        _capacity = capacity;
    }

    public TValue Get(TKey key)
    {
        if (!_cache.ContainsKey(key))
            throw new KeyNotFoundException();

        var node = _cache[key];
        _list.Remove(node);
        _list.AddFirst(node);
        return node.Value.Value;
    }

    public void Put(TKey key, TValue value)
    {
        if (_cache.ContainsKey(key))
        {
            var node = _cache[key];
            node.Value = new KeyValuePair<TKey, TValue>(key, value);
            _list.Remove(node);
            _list.AddFirst(node);
        }
        else if (_list.Count >= _capacity)
        {
            var lastNode = _list.Last;
            if (lastNode != null)
            {
                _cache.Remove(lastNode.Value.Key);
                _list.RemoveLast();
            }
        }

        var newNode = new KeyValuePair<TKey, TValue>(key, value);
        var node = _list.AddFirst(newNode);
        _cache[key] = node;
    }
}

public class Program
{
    static int Main(string[] args)
    {
        LruCache<int, string> cache = new LruCache<int, string>(3);

        cache.Put(1, "One");
        cache.Put(2, "Two");
        cache.Put(3, "Three");

        Console.WriteLine("Get 2: " + cache.Get(2)); // Access 2 (moves to front)

        cache.Put(4, "Four"); // Evicts 1 (least recently used)

        Console.WriteLine("Get 1: " + (cache.Get(1).GetType().Name == "KeyNotFoundException" ? "Not Found" : cache.Get(1)));
        Console.WriteLine("Get 2: " + cache.Get(2)); // Access 2 again

        return 0;
    }
}
