using System;
using System.IO;

public class FolderWatcher
{
    private static FileSystemWatcher watcher;

    public static void Main(string[] args)
    {
        if (args.Length == 0)
        {
            Console.WriteLine("Usage: FolderWatcher <path_to_watch>");
            return;
        }

        string path = args[0];
        if (!Directory.Exists(path))
        {
            Console.WriteLine($"Error: Directory not found at {path}");
            return;
        }

        watcher = new FileSystemWatcher(path);
        watcher.Created += OnFileSystemEvent;
        watcher.Changed += OnFileSystemEvent;
        watcher.Deleted += OnFileSystemEvent;
        watcher.Renamed += OnFileSystemEvent;

        Console.WriteLine($"Watching directory: {Path.GetFullPath(path)}");
        Console.WriteLine("Press Enter to stop watching.");

        // Start the watcher and wait for user input
        watcher.EnableRaisingEvents = true;
        Console.ReadLine();

        // Stop the watcher
        watcher.Dispose();
    }

    private static void OnFileSystemEvent(object sender, FileSystemEventArgs e)
    {
        string action = "";
        if (e is FileSystemEventArgs fse && fse.ChangeType == WatcherChangeType.Created)
            action = "CREATED";
        else if (e is FileSystemEventArgs fse && fse.ChangeType == WatcherChangeType.Changed)
            action = "CHANGED";
        else if (e is FileSystemEventArgs fse && fse.ChangeType == WatcherChangeType.Deleted)
            action = "DELETED";
        else if (e is RenamedEventArgs re)
        {
            if (re.OldName != null)
                Console.WriteLine($"RENAMED: '{re.OldName}' to '{re.Name}'");
            return; // Handled renaming separately for clarity
        }

        if (!string.IsNullOrEmpty(action))
        {
            Console.WriteLine($"{action}: {e.FullPath}");
        }
    }
}
