        -- This exception is unlikely for a simple UPDATE but included for completeness
        DBMS_OUTPUT.PUT_LINE('Error: Multiple departments matched the criteria.');
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('An unexpected error occurred: ' || SQLCODE || ' - ' || SQLERRM);
END;
