    -- Bulk collect IDs of inactive accounts
    SELECT account_id BULK COLLECT INTO v_inactive_ids
    FROM user_accounts
    WHERE status = 'INACTIVE';

    -- Deactivate them using FORALL
    FORALL i IN 1 .. v_inactive_ids.COUNT
        UPDATE user_accounts
        SET status = 'DEACTIVATED'
        WHERE account_id = v_inactive_ids(i);

    COMMIT;
END;
